import itertools
U = range(5); S = [set(c) for r in range(4) for c in itertools.combinations(U, r)]
ok = {k: True for k in 'ABCD'}
for T in S:
    for D in S:
        for F in S:
            want = T <= (D | F)  # every name in Team is a Defender name or a Forward name
            got = {'A': not (T - (D & F)), 'B': not ((D & F) - T),
                   'C': not (T - (D | F)), 'D': not ((D | F) - T)}
            for k in ok: ok[k] &= (got[k] == want)
print(ok); assert ok == {'A': False, 'B': False, 'C': True, 'D': False}  # only C matches the condition on every instance
